contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public payable {
        require(_tos.length > 0);

        bool firstReverted;
        try c.transfer(from, caddress, _tos, v, _decimals) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        bool emptyReverted;
        address[] memory empty = new address[](0);
        try c.transfer(from, caddress, empty, v, _decimals) {
            emptyReverted = false;
        } catch {
            emptyReverted = true;
        }

        bool reversedReverted;
        try c.transfer(from, from, _tos, v, _decimals) {
            reversedReverted = false;
        } catch {
            reversedReverted = true;
        }

        assert((!firstReverted && !emptyReverted && !reversedReverted) || (firstReverted && emptyReverted && reversedReverted));
    }
}

